// 组装沙箱策略：命令白名单 / 参数黑名单 / 网络白名单 / 配额
const body = $json.body || {};
const allowed = (process.env.SANDBOX_ALLOWED_COMMANDS || 'ls,cat,git,python3,node,grep,find').split(',');
const netAllow = (process.env.SANDBOX_NETWORK_ALLOWLIST || 'api.openai.com,api.github.com').split(',');
const policy = {
  allowed_commands: allowed,
  blocked_patterns: [/rm\s+-rf/i, /curl[^|]*\|\s*(sh|bash)/i, /chmod\s+777/i, /mkfs/i, /:\(\)\{.*\};:/i],
  network_allowlist: netAllow,
  network_enabled: !!body.network,
  max_seconds: parseInt(process.env.SANDBOX_MAX_SECONDS || '300', 10),
  max_output_bytes: parseInt(process.env.SANDBOX_MAX_OUTPUT_BYTES || String(50 * 1024 * 1024), 10),
  workdir: body.workdir || './workspace'
};
const cmd = String(body.command || '');
let risk = 0.0; const reasons = [];
const head = cmd.trim().split(/\s+/)[0] || '';
if (!allowed.includes(head)) { risk = Math.max(risk, 0.9); reasons.push('cmd_not_allowed:' + head); }
for (const re of policy.blocked_patterns) { if (re.test(cmd)) { risk = Math.max(risk, 0.95); reasons.push('blocked_pattern:' + re.source); } }
const action = risk >= 0.85 ? 'BLOCK' : (risk >= 0.6 ? 'REVIEW' : 'PASS');
return [{ json: { command: cmd, policy, risk, reasons, action } }];

// 在临时沙箱中执行命令（受限实现示例：命令白名单 + 超时 + 输出截断）
const { command, policy } = $json;
if ($json.action === 'BLOCK') {
  return [{ json: { ok: false, stdout: '', stderr: 'blocked by policy', exit_code: 126, duration_ms: 0, truncated: false, action: 'BLOCK' } }];
}
const { execFileSync } = require('child_process');
const head = command.trim().split(/\s+/)[0];
const args = command.trim().split(/\s+/).slice(1);
const started = Date.now();
let stdout = '', stderr = '', exit_code = 0, truncated = false;
try {
  stdout = execFileSync(head, args, { timeout: policy.max_seconds * 1000, encoding: 'utf8', maxBuffer: policy.max_output_bytes });
} catch (e) {
  stdout = (e.stdout || '').toString(); stderr = (e.stderr || '').toString();
  exit_code = typeof e.status === 'number' ? e.status : 1;
  if (e.signal) stderr += '\n[signal] ' + e.signal;
}
if (stdout.length > policy.max_output_bytes) { stdout = stdout.slice(0, policy.max_output_bytes); truncated = true; }
return [{ json: { ok: exit_code === 0, stdout, stderr, exit_code, duration_ms: Date.now() - started, truncated, action: $json.action } }];

// 校验实际耗时与输出大小，超限即熔断
const r = $json;
const policy = $('Policy Builder').first().json.policy;
let action = r.action || 'PASS';
const reasons = $('Policy Builder').first().json.reasons || [];
if (r.duration_ms > policy.max_seconds * 1000) { action = 'BLOCK'; reasons.push('timeout'); }
if (r.stdout && r.stdout.length >= policy.max_output_bytes) { action = 'REVIEW'; reasons.push('output_truncated'); }
if (r.exit_code !== 0) { action = action === 'BLOCK' ? 'BLOCK' : 'REVIEW'; reasons.push('exit_' + r.exit_code); }
return [{ json: { ...r, action, reasons } }];

// 审计留痕（JSONL）
const fs = require('fs');
const path = process.env.SANDBOX_AUDIT_PATH || '/tmp/sandbox_audit.jsonl';
const r = $json;
const rec = {
  ts: new Date().toISOString(),
  task_id: $('Sandbox Webhook').first().json.body.task_id || null,
  command: $('Policy Builder').first().json.command,
  exit_code: r.exit_code,
  duration_ms: r.duration_ms,
  truncated: !!r.truncated,
  action: r.action,
  reasons: r.reasons || []
};
try { fs.appendFileSync(path, JSON.stringify(rec) + '\n'); } catch (e) { /* ignore */ }
return [{ json: { ...r, audit_path: path } }];

// 用完即焚：清理沙箱工作目录，仅保留审计元数据
const fs = require('fs');
const path = require('path');
const base = process.env.SANDBOX_BASE_DIR || '/tmp/agent-sandbox';
const dir = path.join(base, 'task-' + Date.now());
let cleaned = false;
try { if (fs.existsSync(dir)) { fs.rmSync(dir, { recursive: true, force: true }); cleaned = true; } } catch (e) { /* ignore */ }
return [{ json: { ...$json, sandbox_cleaned: cleaned } }];
